        text: "System-Anpassung. Content so verschieben, dass Spielerentscheidungen und Konsequenzen sichtbar werden. Trailer-Opening umsortieren, damit Interaktion früher kommt. Screenshots aktualisieren, damit Gameplay-Kontext lesbar wird.",
